153	      if (this.retryOpts.statusCodes.includes(statusCode) === false) {
154	        this.headersSent = true
155	        this.checkpointResponseEnd(headers)
156	        this.handler.onResponseStart?.(this.controllerProxy, statusCode, headers, statusMessage)
157	      } else {
158	        this.error = err
159	      }
160	
161	      return
162	    }
163	
164	    if (isDisturbed(this.opts.body)) {
165	      this.headersSent = true
166	      this.checkpointResponseEnd(headers)
167	      this.handler.onResponseStart?.(this.controllerProxy, statusCode, headers, statusMessage)
168	      return
169	    }
