171	    function shouldRetry (passedErr) {
172	      if (this.aborted) {
173	        // Aborted while the policy was deciding; the decision is moot.
174	        return
175	      }
176	      this.retryPending = false
177	      this.retryTimer = null
178	
179	      if (passedErr) {
180	        this.headersSent = true
181	        this.checkpointResponseEnd(headers)
182	        this.handler.onResponseStart?.(this.controllerProxy, statusCode, headers, statusMessage)
