273	      cb(err)
274	      return
275	    }
276	
277	    // If a set of status code are provided and the current status code is not in the list
278	    if (
279	      statusCode != null &&
280	      Array.isArray(statusCodes) &&
281	      !statusCodes.includes(statusCode)
282	    ) {
283	      cb(err)
284	      return
285	    }
286	
287	    // If we reached the max number of retries
288	    if (counter > maxRetries) {
289	      cb(err)
290	      return
291	    }
