407	        this.start = start
408	        this.end = end
409	      }
410	
411	      // We make our best to checkpoint the body for further range headers
412	      if (this.end == null && this.opts.method !== 'HEAD') {
413	        const contentLength = headers['content-length']
414	        this.end = contentLength != null ? Number(contentLength) - 1 : null
415	      }
416	
417	      assert(Number.isFinite(this.start))
418	      assert(
419	        this.end == null || Number.isFinite(this.end),
420	        'invalid content-length'
421	      )
422	
423	      this.resume = true
424	      this.etag = headers.etag != null ? headers.etag : null
425	
426	      // Weak etags are not useful for comparison nor cache
427	      // for instance not safe to assume if the response is byte-per-byte
428	      // equal
429	      if (
430	        this.etag != null &&
431	        this.etag[0] === 'W' &&
432	        this.etag[1] === '/'
433	      ) {
434	        this.etag = null
435	      }
436	
437	      this.headersSent = true
438	      this.handler.onResponseStart?.(
439	        this.controllerProxy,
440	        statusCode,
441	        headers,
442	        statusMessage
443	      )
444	    } else {
445	      throw new RequestRetryError('Request failed', statusCode, {
446	        headers,
447	        data: { count: this.retryCount }
448	      })
449	    }
450	  }
451	
452	  onResponseData (_controller, chunk) {
453	    if (this.error) {
454	      return
455	    }
456	
457	    this.start += chunk.length
458	
459	    this.handler.onResponseData?.(this.controllerProxy, chunk)
460	  }
461	
462	  onResponseEnd (_controller, trailers) {
463	    if (this.error && this.retryOpts.throwOnError) {
464	      throw this.error
465	    }
466	
467	    if (!this.error) {
468	      // Verify that the received body length matches the expected range
469	      // when we have a finite end position (from Content-Length or Content-Range)
470	      if (this.end != null && Number.isFinite(this.end)) {
471	        if (this.start !== this.end + 1) {
472	          throw new RequestRetryError('Content-Range mismatch', this.statusCode, {
473	            headers: this.headers,
474	            data: { count: this.retryCount }
475	          })
476	        }
477	      }
478	      this.retryCount = 0
479	      return this.handler.onResponseEnd?.(this.controllerProxy, trailers)
480	    }
481	
482	    this.retry()
483	  }
484	
485	  retry () {
486	    if (this.start !== 0) {
487	      const headers = { range: `bytes=${this.start}-${this.end ?? ''}` }
488	
489	      // Weak etag check - weak etags will make comparison algorithms never match
490	      if (this.etag != null) {
491	        headers['if-match'] = this.etag
492	      }
493	
494	      this.opts = {
495	        ...this.opts,
496	        headers: {
497	          ...this.opts.headers,
498	          ...headers
499	        }
500	      }
501	    }
502	
503	    try {
504	      this.retryCountCheckpoint = this.retryCount
505	      this.dispatch(this.opts, this)
506	    } catch (err) {
507	      this.handler.onResponseError?.(this.controllerProxy, err)
508	    }
509	  }
510	
511	  onResponseError (controller, err) {
512	    if (this.aborted) {
513	      // #onAbort already delivered the terminal error downstream; the late
514	      // error of the torn-down connection must not be forwarded twice.
515	      return
516	    }
517	
518	    // controller is THIS failed connection (not the proxy): we inspect whether
519	    // the consumer aborted it to decide retry-vs-propagate.
520	    if (controller?.aborted || isDisturbed(this.opts.body) || (this.headersSent && !this.resume)) {
521	      this.handler.onResponseError?.(this.controllerProxy, err)
522	      return
523	    }
524	
525	    function shouldRetry (returnedErr) {
526	      if (this.aborted) {
527	        // Aborted while the policy was deciding; the decision is moot.
528	        return
529	      }
530	      this.retryPending = false
531	      this.retryTimer = null
532	
533	      if (!returnedErr) {
534	        this.retry()
535	        return
536	      }
537	
538	      this.handler?.onResponseError?.(this.controllerProxy, returnedErr)
539	    }
540	
541	    // We reconcile in case of a mix between network errors
542	    // and server error response
543	    if (this.retryCount - this.retryCountCheckpoint > 0) {
544	      // We count the difference between the last checkpoint and the current retry count
545	      this.retryCount =
546	        this.retryCountCheckpoint +
547	        (this.retryCount - this.retryCountCheckpoint)
548	    } else {
549	      this.retryCount += 1
550	    }
551	
552	    this.retryPending = true
553	    this.retryTimer = this.retryOpts.retry(
554	      err,
555	      {
556	        state: { counter: this.retryCount },
557	        opts: { retryOptions: this.retryOpts, ...this.opts }
558	      },
559	      shouldRetry.bind(this)
560	    ) ?? null
561	  }
562	
563	  #onAbort (reason) {
564	    // A consumer abort lands on the controller proxy. If the retry policy is
565	    // still deciding (typically holding a backoff timer), cancel the wait and
566	    // surface the abort immediately instead of letting the request hang until
567	    // the backoff elapses.
568	    if (!this.retryPending) {
569	      return
570	    }
571	
572	    this.aborted = true
573	    this.retryPending = false
574	    clearTimeout(this.retryTimer)
575	    this.retryTimer = null
576	    this.handler.onResponseError?.(this.controllerProxy, reason ?? new RequestAbortedError())
577	  }
578	}
579	
580	module.exports = RetryHandler
