'use strict'

const { tspl } = require('@matteo.collina/tspl')
const { test, after } = require('node:test')
const { createServer } = require('node:net')
const { once } = require('node:events')

const { Client, interceptors } = require('..')

// A terminal retry decision can land *after* another dispatch of the same
// request already exposed a response to the caller. Forwarding it as a
// replacement response orphans the body being read: it never ends and never
// errors. The terminal error must settle the exposed body instead.
test('settles the already exposed body when a stale retry decision fails', async t => {
  t = tspl(t, { plan: 3 })

  let connections = 0
  const server = createServer(socket => {
    connections++
    socket.on('error', () => {})
    socket.once('data', () => {
      if (connections === 1) {
        // Retryable status, then the connection dies before the body arrives:
        // two retry decisions end up pending for the same request.
        socket.write('HTTP/1.1 503 Service Unavailable\r\ncontent-length: 5\r\n\r\n')
        setTimeout(() => socket.destroy(), 50)
      } else {
        // Still streaming when the stale 503 decision becomes terminal.
        socket.write('HTTP/1.1 200 OK\r\ncontent-length: 10\r\n\r\nhello')
        setTimeout(() => socket.write('world'), 500)
      }
    })
  })
  after(() => server.close())

  server.listen(0)
  await once(server, 'listening')

  const client = new Client(`http://localhost:${server.address().port}`)
    .compose(interceptors.retry({
      throwOnError: false,
      maxRetries: 5,
      retry (err, _state, cb) {
        if (err.statusCode === 503) {
          // A policy that takes its time to reach a terminal decision.
          return setTimeout(() => cb(err), 250)
        }
        cb(null)
      }
    }))
  after(() => client.close())

  const res = await client.request({ method: 'GET', path: '/' })
  t.strictEqual(res.statusCode, 200)

  // The exposed body must settle -- with data or with the terminal error --
  // rather than hang forever.
  await t.rejects(res.body.text(), { code: 'UND_ERR_REQ_RETRY' })
  t.strictEqual(connections, 2)
})

